func:
// Work mode settings
// 243: Energy management model
// 244: Limit control function
// 245: Max grid export power
// 246: (skip)
// 247: Solar sell enable

msg.baseAddr = 243;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 243,
    quantity: 5
};
return msg;

// Time of Use enable and days
// 248: bit0=enable, bit1-7=days

msg.baseAddr = 248;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 248,
    quantity: 1
};
return msg;

// TOU time points (6 slots)
// 250-255: Sell mode time point 1-6 (HHMM)

msg.baseAddr = 250;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 250,
    quantity: 6
};
return msg;

// TOU discharge power limits (6 slots)
// 256-261: Sell mode time point 1-6 power (1W)

msg.baseAddr = 256;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 256,
    quantity: 6
};
return msg;

// TOU voltage thresholds (6 slots)
// 262-267: Sell mode time point 1-6 voltage (0.01V)

msg.baseAddr = 262;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 262,
    quantity: 6
};
return msg;

// TOU SOC thresholds (6 slots)
// 268-273: Capacity 1-6 (1% SOC)

msg.baseAddr = 268;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 268,
    quantity: 6
};
return msg;

// TOU charge enable flags (6 slots)
// 274-279: Time point 1-6 charge enable
//   bit0: grid charge
//   bit1: generator charge

msg.baseAddr = 274;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 274,
    quantity: 6
};
return msg;

// Grid peak shaving
// 280: Advanced bits (bit8-11 = grid peak shaving)
// We read 280 separately, 293 separately
// This node reads 293

msg.baseAddr = 293;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 293,
    quantity: 1
};
return msg;

// Force off-grid operation
// 416: 强制离网运行位

msg.baseAddr = 416;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 416,
    quantity: 1
};
return msg;

// Build SystemWorkModeConfigState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("SystemWorkModeConfigState: missing base address");
    return null;
}

// Helper: parse HHMM to time string
function parseHHMM(val) {
    if (!val || val === 0) return "00:00";
    const hh = Math.floor(val / 100);
    const mm = val % 100;
    return String(hh).padStart(2, '0') + ":" + String(mm).padStart(2, '0');
}

// ---- Store partials ----

// WorkMode 243-247
if (baseAddr === 243) {
    const workModeCode = data[0] || 0;        // 243
    const zeroExportLimit = data[1] || 0;     // 244
    const maxSellPower = data[2] || 0;        // 245
    // data[3] = 246 (skip)
    const solarSell = data[4] || 0;           // 247

    flow.set("swm_part_workmode", {
        workModeCode: workModeCode,
        zeroExportLimitPowerW: zeroExportLimit,
        maxSellPowerW: maxSellPower,
        solarSellEnabled: solarSell === 1
    });
}

// TOU Enable 248
else if (baseAddr === 248) {
    const bits = data[0] || 0;
    flow.set("swm_part_tou_enable", {
        touEnabled: (bits & 0x01) === 1,
        monday: ((bits >> 1) & 0x01) === 1,
        tuesday: ((bits >> 2) & 0x01) === 1,
        wednesday: ((bits >> 3) & 0x01) === 1,
        thursday: ((bits >> 4) & 0x01) === 1,
        friday: ((bits >> 5) & 0x01) === 1,
        saturday: ((bits >> 6) & 0x01) === 1,
        sunday: ((bits >> 7) & 0x01) === 1
    });
}

// TOU Times 250-255
else if (baseAddr === 250) {
    flow.set("swm_part_tou_times", data.map(v => parseHHMM(v)));
}

// TOU Power 256-261
else if (baseAddr === 256) {
    flow.set("swm_part_tou_power", data.slice(0, 6));
}

// TOU Voltage 262-267
else if (baseAddr === 262) {
    flow.set("swm_part_tou_voltage", data.slice(0, 6).map(v => Math.round(v * 0.01 * 100) / 100));
}

// TOU SOC 268-273
else if (baseAddr === 268) {
    flow.set("swm_part_tou_soc", data.slice(0, 6));
}

// TOU Charge 274-279
else if (baseAddr === 274) {
    flow.set("swm_part_tou_charge", data.slice(0, 6).map(v => ({
        allowGridCharge: (v & 0x01) === 1,
        allowGeneratorCharge: ((v >> 1) & 0x01) === 1
    })));
}

// Peak Shaving 293
else if (baseAddr === 293) {
    flow.set("swm_part_peak_shaving", {
        gridPeakShavingPowerW: data[0] || 0
    });
}

// Force OffGrid 416
else if (baseAddr === 416) {
    flow.set("swm_part_force_offgrid", {
        forceOffGrid: (data[0] || 0) === 1
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const workmodePart = flow.get("swm_part_workmode");
const touEnablePart = flow.get("swm_part_tou_enable");
const touTimesPart = flow.get("swm_part_tou_times");
const touPowerPart = flow.get("swm_part_tou_power");
const touVoltagePart = flow.get("swm_part_tou_voltage");
const touSocPart = flow.get("swm_part_tou_soc");
const touChargePart = flow.get("swm_part_tou_charge");
const peakShavingPart = flow.get("swm_part_peak_shaving");
const forceOffgridPart = flow.get("swm_part_force_offgrid");

// Need advBits from GeneratorAndSmartLoadConfigState (register 280)
// If not available, we can read it separately or use cached value
const gslSnapshot = flow.get("generatorSmartLoadConfigSnapshot");
const advBitsRaw = gslSnapshot ? gslSnapshot._debug.advBitsRaw : 0;
const gridPeakShavingEnabled = ((advBitsRaw >> 8) & 0x0F) > 0;

if (!workmodePart || !touEnablePart || !touTimesPart || !touPowerPart || 
    !touVoltagePart || !touSocPart || !touChargePart || !peakShavingPart || !forceOffgridPart) {
    return null;
}

const gatewayId = global.get("GATEWAY_ID") || env.get("GATEWAY_ID") || "EC100-GW-001";
const inverterSN = global.get("INVERTER_SN") || env.get("INVERTER_SN") || "Unknown";

// Derive userModeProfile
let userModeProfile = "custom";
if (touEnablePart.touEnabled) {
    userModeProfile = "time_of_use";
} else if (workmodePart.workModeCode === 0) {
    userModeProfile = "self_consumption";
} else if (workmodePart.workModeCode === 1) {
    userModeProfile = "backup";
}

// Derive exportStrategy
let exportStrategy = "selling_first";
if (workmodePart.zeroExportLimitPowerW > 0) {
    exportStrategy = "zero_export_to_ct";
} else if (!workmodePart.solarSellEnabled) {
    exportStrategy = "zero_export_to_load";
}

// Build TOU slots
const slots = [];
for (let i = 0; i < 6; i++) {
    const startTime = touTimesPart[i] || "00:00";
    const endTime = touTimesPart[(i + 1) % 6] || "00:00";  // Next slot start = this slot end

    slots.push({
        slotIndex: i + 1,
        startTimeLocal: startTime,
        endTimeLocal: endTime,
        allowGridCharge: touChargePart[i] ? touChargePart[i].allowGridCharge : false,
        allowGeneratorCharge: touChargePart[i] ? touChargePart[i].allowGeneratorCharge : false,
        sellEnabledInThisSlot: true,  // Derived - assume enabled if configured
        maxBatteryDischargePowerW: touPowerPart[i] || 0,
        batteryThresholdSocPercent: touSocPart[i] || null,
        batteryThresholdVoltageV: touVoltagePart[i] || null
    });
}

const state = {
    kind: "SystemWorkModeConfigState",
    timestampUtc: new Date().toISOString(),
    gatewayId: gatewayId,
    inverterSerialNumber: inverterSN,
    version: 1,

    userModeProfile: userModeProfile,

    inverterMode: {
        workModeCode: workmodePart.workModeCode,
        exportStrategy: exportStrategy,
        solarSellEnabled: workmodePart.solarSellEnabled,
        maxSellPowerW: workmodePart.maxSellPowerW,
        defaultMaxSellPowerW: null,
        zeroExportLimitPowerW: workmodePart.zeroExportLimitPowerW,
        forceOffGrid: forceOffgridPart.forceOffGrid
    },

    energyPriority: {
        pattern: workmodePart.workModeCode === 0 ? "battery_first" : "load_first"
    },

    gridPeakShaving: {
        enabled: gridPeakShavingEnabled,
        limitPowerW: peakShavingPart.gridPeakShavingPowerW
    },

    timeOfUse: {
        enabled: touEnablePart.touEnabled,
        daysActive: {
            monday: touEnablePart.monday,
            tuesday: touEnablePart.tuesday,
            wednesday: touEnablePart.wednesday,
            thursday: touEnablePart.thursday,
            friday: touEnablePart.friday,
            saturday: touEnablePart.saturday,
            sunday: touEnablePart.sunday
        },
        slots: slots
    }
};

// Clear partials
flow.set("swm_part_workmode", null);
flow.set("swm_part_tou_enable", null);
flow.set("swm_part_tou_times", null);
flow.set("swm_part_tou_power", null);
flow.set("swm_part_tou_voltage", null);
flow.set("swm_part_tou_soc", null);
flow.set("swm_part_tou_charge", null);
flow.set("swm_part_peak_shaving", null);
flow.set("swm_part_force_offgrid", null);

flow.set("systemWorkModeConfigSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;
